import json

def validate_payload(payload):
    required = ["name", "email", "age"]
    for key in required:
        if key not in payload:
            print(f"Missing key: {key}")
            return False
    print("Payload valid")
    return True

payload = {"name": "Bob", "age": 30}
validate_payload(payload)

