import json

def validate_types(payload):
    if "age" in payload and not isinstance(payload["age"], (int, float)):
        print("age must be a number")
        return
    if "tags" in payload and not isinstance(payload["tags"], list):
        print("tags must be a list")
        return
    if "email" in payload and not isinstance(payload["email"], str):
        print("email must be a string")
        return
    if "active" in payload and not isinstance(payload["active"], bool):
        print("active must be a bool")
        return
    print("All types valid")

payload = {"name": "Bob", "age": "thirty", "tags": ["user"], "active": True}
validate_types(payload)
